function printFesselung(B,w){const brett=(fen,lab,fill)=>`<div style="text-align:center">${diag({fen},fill?{fill}:{})}<p><b>${lab}</b></p></div>`;
 return B.sheetCSS('Fesselung')+PCSS+`<section class="ws-page jp-poster jp-heft">${head('Die Fesselung','Plakat · Silber · Woche '+w)}<p style="font-size:16pt;text-align:center;margin:2mm 0 4mm"><b>Angreifer · Figur · König auf einer Linie: Die Figur ist gefesselt.</b></p><table class="ws-table"><tbody><tr><td style="width:46mm;font-size:14pt"><b>An den König</b></td><td style="font-size:12.5pt">Die Figur darf die Linie nicht verlassen, sonst stünde der eigene König im Schach. Ein Springer darf dann gar nicht ziehen.</td></tr><tr><td style="font-size:14pt"><b>An die Dame</b></td><td style="font-size:12.5pt">Die Figur darf ziehen, aber dann geht die Dame verloren.</td></tr><tr><td style="font-size:14pt"><b>Wer fesselt?</b></td><td style="font-size:12.5pt">Nur Läufer, Turm und Dame, denn sie ziehen weit auf Linien.</td></tr><tr><td style="font-size:14pt"><b>Ausnutzen</b></td><td style="font-size:12.5pt">Die gefesselte Figur noch einmal angreifen, am besten mit einem Bauern. Sie kann nicht weglaufen.</td></tr><tr><td style="font-size:14pt"><b>Befreien</b></td><td style="font-size:12.5pt">Den König aus der Linie ziehen, eine Figur dazwischenstellen oder den Fesselnden angreifen.</td></tr></tbody></table><div class="ws-grid" style="grid-template-columns:1fr 1fr">${brett('r1bqkbnr/ppp2ppp/2np4/1B2p3/4P3/5N2/PPPP1PPP/RNBQK2R','An den König: Der Springer c6 darf nicht ziehen.')}${brett('rnbqkb1r/pp3ppp/2p1pn2/3p2B1/2PP4/2N1P3/PP3PPP/R2QKBNR','An die Dame: Zieht der Springer f6, ist die Dame d8 weg.')}</div><p class="ws-src">© Dr. Edmund Bruns</p></section>`}
